Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

struct Pos {
    int r, c;
    Pos(int rr = 0, int cc = 0) : r(rr), c(cc) {}
};

int N, T, W;
vector<string> B;
vector<int> D1, D2;
const int dr[4] = {-1, 0, 0, 1};
const int dc[4] = {0, -1, 1, 0};

inline int idx(int r, int c) { return r * W + c; }

void bfs_from_z(const Pos& z) {
    D1.assign(W * W, -1);
    vector<int> q;
    q.reserve(W * W);
    int head = 0;
    D1[idx(z.r, z.c)] = 0;
    q.push_back(idx(z.r, z.c));
    while (head < (int)q.size()) {
        int cur = q[head++];
        int r = cur / W, c = cur % W;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (B[nr][nc] != '.') continue;
            int ni = idx(nr, nc);
            if (D1[ni] != -1) continue;
            D1[ni] = D1[cur] + 1;
            q.push_back(ni);
        }
    }
}

void bfs_from_scientist(const Pos& s) {
    D2.assign(W * W, -1);
    vector<int> q;
    q.reserve(W * W);
    int head = 0;
    D2[idx(s.r, s.c)] = 0;
    q.push_back(idx(s.r, s.c));
    while (head < (int)q.size()) {
        int cur = q[head++];
        int r = cur / W, c = cur % W;
        if (D1[cur] >= 0 && D2[cur] >= D1[cur]) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (B[nr][nc] != '.') continue;
            int ni = idx(nr, nc);
            if (D2[ni] != -1) continue;
            if (D1[ni] >= 0 && D1[ni] < D2[cur] + 1) continue;
            D2[ni] = D2[cur] + 1;
            q.push_back(ni);
        }
    }
}

int max_flow(int s, int t, vector<vector<int> > cap) {
    int n = (int)cap.size();
    int flow = 0;
    while (true) {
        vector<int> pre(n, -1);
        vector<int> q;
        q.reserve(n);
        int head = 0;
        pre[s] = s;
        q.push_back(s);
        while (head < (int)q.size() && pre[t] == -1) {
            int u = q[head++];
            for (int v = 0; v < n; ++v) {
                if (pre[v] == -1 && cap[u][v] > 0) {
                    pre[v] = u;
                    q.push_back(v);
                    if (v == t) break;
                }
            }
        }
        if (pre[t] == -1) break;
        int add = INT_MAX;
        for (int v = t; v != s; v = pre[v])
            add = min(add, cap[pre[v]][v]);
        for (int v = t; v != s; v = pre[v]) {
            cap[pre[v]][v] -= add;
            cap[v][pre[v]] += add;
        }
        flow += add;
    }
    return flow;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    W = N + 2;

    B.assign(W, string(W, '#'));
    string line;
    for (int r = 1; r <= N; ++r) {
        cin >> line;
        for (int c = 1; c <= N; ++c) B[r][c] = line[c - 1];
    }
    vector<string> B1 = B;

    vector<string> B2(W, string(W, '#'));
    for (int r = 1; r <= N; ++r) {
        cin >> line;
        for (int c = 1; c <= N; ++c) B2[r][c] = line[c - 1];
    }

    vector<Pos> scientists, capsules;
    Pos z;
    for (int r = 1; r <= N; ++r) {
        for (int c = 1; c <= N; ++c) {
            char ch = B[r][c];
            if (ch >= '0' && ch <= '9') {
                if (ch > '0') scientists.push_back(Pos(r, c));
                B[r][c] = '.';
            } else if (ch == 'Z') {
                z = Pos(r, c);
                B[r][c] = '.';
            }
            char ch2 = B2[r][c];
            if (ch2 >= '0' && ch2 <= '9' && ch2 > '0')
                capsules.push_back(Pos(r, c));
        }
    }

    bfs_from_z(z);

    int nS = (int)scientists.size();
    int nC = (int)capsules.size();
    int SRC = 0;
    int SINK = nS + nC + 1;
    vector<vector<int> > cap(SINK + 1, vector<int>(SINK + 1, 0));
    const int INF = 98765432;

    for (int i = 0; i < nS; ++i) {
        const Pos& s = scientists[i];
        cap[SRC][i + 1] += B1[s.r][s.c] - '0';
    }
    for (int j = 0; j < nC; ++j) {
        const Pos& c = capsules[j];
        cap[nS + j + 1][SINK] += B2[c.r][c.c] - '0';
    }

    for (int i = 0; i < nS; ++i) {
        const Pos& s = scientists[i];
        bfs_from_scientist(s);
        for (int j = 0; j < nC; ++j) {
            const Pos& c = capsules[j];
            int ci = idx(c.r, c.c);
            if (D2[ci] >= 0 && D2[ci] <= T)
                cap[i + 1][nS + j + 1] = INF;
        }
    }

    cout << max_flow(SRC, SINK, cap) << '\n';
    return 0;
}
